 "content": "def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # identify grid separators
    rs=[i for i,r in enumerate(grid) if all(v==8 for v in r)]
    cs=[j for j in range(w) if all(grid[i][j]==8 for i in range(h))]
    rb=[-1]+rs+[h]; cb=[-1]+cs+[w]
    rh=[(rb[i]+1,rb[i+1]) for i in range(len(rb)-1)]
    cw=[(cb[i]+1,cb[i+1]) for i in range(len(cb)-1)]
    marks={}
    for i in range(len(rh)):
      for j in range(len(cw)):
        a,b=rh[i]; c,d=cw[j]
        vals=[grid[y][x] for y in range(a,b) for x in range(c,d) if grid[y][x] not in (0,8)]
        if vals: marks.setdefault(vals[0],[]).append((i,j))
    paint={}
    for color,pts in marks.items():
      for (r1,c1),(r2,c2) in __import__('itertools').combinations(pts,2):
        if r1==r2:
          for c in range(min(c1,c2),max(c1,c2)+1): paint.setdefault((r1,c),set()).add(color)
        if c1==c2:
          for r in range(min(r1,r2),max(r1,r2)+1): paint.setdefault((r,c1),set()).add(color)
    for (i,j),colors in paint.items():
      val=next(iter(colors)) if len(colors)==1 else 6 if colors=={2,3} else max(colors)
      a,b=rh[i]; c,d=cw[j]
      for y in range(a,b):
       for x in range(c,d): out[y][x]=val
    return out
